import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { isSandboxNetworkEnforced, resolveSandboxPosture } from '../../lib/sandbox-posture.js';

// #3322. Real files in a temp project + temp home, no mocks: the resolver is
// the only reader of these four scopes and the precedence must match CC's.

let proj: string;
let home: string;
function put(rel: string, obj: unknown): void {
  const full = join(rel.startsWith('home/') ? home : proj, rel.replace(/^home\//, ''));
  mkdirSync(join(full, '..'), { recursive: true });
  writeFileSync(full, JSON.stringify(obj));
}
beforeEach(() => { proj = mkdtempSync(join(tmpdir(), 'sbx-proj.')); home = mkdtempSync(join(tmpdir(), 'sbx-home.')); });
afterEach(() => { rmSync(proj, { recursive: true, force: true }); rmSync(home, { recursive: true, force: true }); });

describe('resolveSandboxPosture', () => {
  it('reports unknown with no settings anywhere', () => {
    expect(resolveSandboxPosture(proj, home)).toEqual({ enabled: 'unknown', network: 'none', source: '' });
  });

  it('reads user settings.json, where real configs live (doctor Check 15 was blind to it)', () => {
    put('home/.claude/settings.json', { sandbox: { enabled: true, network: { allowedDomains: ['github.com'] } } });
    const p = resolveSandboxPosture(proj, home);
    expect(p.enabled).toBe('true');
    expect(p.network).toBe('allowlist');
    expect(p.source).toBe(join(home, '.claude', 'settings.json'));
  });

  it('project local wins over user for enabled', () => {
    put('home/.claude/settings.json', { sandbox: { enabled: true } });
    put('.claude/settings.local.json', { sandbox: { enabled: false } });
    expect(resolveSandboxPosture(proj, home).enabled).toBe('false');
  });

  it('classifies a denylist-only network block', () => {
    put('.claude/settings.json', { sandbox: { enabled: true, network: { deniedDomains: ['pastebin.com'] } } });
    expect(resolveSandboxPosture(proj, home).network).toBe('denylist');
  });

  it('treats an unreadable settings file as absent', () => {
    mkdirSync(join(proj, '.claude'), { recursive: true });
    writeFileSync(join(proj, '.claude', 'settings.json'), '{not json');
    put('home/.claude/settings.json', { sandbox: { enabled: true } });
    expect(resolveSandboxPosture(proj, home).enabled).toBe('true');
  });
});

describe('isSandboxNetworkEnforced', () => {
  it('is true only for enabled + a network policy', () => {
    expect(isSandboxNetworkEnforced(undefined, { ORK_SANDBOX_ENABLED: 'true', ORK_SANDBOX_NETWORK: 'allowlist' })).toBe(true);
    expect(isSandboxNetworkEnforced(undefined, { ORK_SANDBOX_ENABLED: 'true', ORK_SANDBOX_NETWORK: 'denylist' })).toBe(true);
    expect(isSandboxNetworkEnforced(undefined, { ORK_SANDBOX_ENABLED: 'true', ORK_SANDBOX_NETWORK: 'none' })).toBe(false);
    expect(isSandboxNetworkEnforced(undefined, { ORK_SANDBOX_ENABLED: 'unknown', ORK_SANDBOX_NETWORK: 'allowlist' })).toBe(false);
    expect(isSandboxNetworkEnforced(undefined, {})).toBe(false);
  });

  it('reads the project settings when the env carries no override', () => {
    put('.claude/settings.json', { sandbox: { enabled: true, network: { deniedDomains: ['pastebin.com'] } } });
    expect(isSandboxNetworkEnforced(proj, {}, home)).toBe(true);
    put('.claude/settings.json', { sandbox: { enabled: true } });
    expect(isSandboxNetworkEnforced(proj, {}, home)).toBe(false);
  });
});
